mapper.select:
SELECT s.*
FROM song s
JOIN song_tag st ON s.id = st.song_id
WHERE st.tag_id = #{tagId}
ORDER BY st.create_time DESC
LIMIT #{limit}

SELECT s.id, s.singer_id, s.name, s.introduction, s.create_time, s.update_time, s.pic, s.url, COUNT(DISTINCT st.tag_id) as match_count FROM song s JOIN song_tag st ON s.id = st.song_id WHERE st.tag_id IN
#{tagId}
GROUP BY s.id ORDER BY match_count DESC, MAX(st.create_time) DESC LIMIT #{limit}
